40	/* Axis-aligned segment as one rectangle, caps included. */
41	static void axis_aligned(Canvas *c, wide_t x1, wide_t y1, wide_t x2, wide_t y2,
42	                         int cap1, int cap2, int w, uint16_t colour) {
43	  const wide_t before = w / 2;
44	  const wide_t ext = w / 2;
45	  if (y1 == y2) {
46	    const int lo_cap = x1 <= x2 ? cap1 : cap2, hi_cap = x1 <= x2 ? cap2 : cap1;
47	    const wide_t xa = min_w(x1, x2) - (lo_cap == CapProjecting ? ext : 0);
48	    const wide_t xb = max_w(x1, x2) + (hi_cap == CapProjecting ? ext : 0);
49	    fill_box(c, xa, y1 - before, xb, y1 - before + w - 1, colour);
50	  } else {
51	    const int lo_cap = y1 <= y2 ? cap1 : cap2, hi_cap = y1 <= y2 ? cap2 : cap1;
52	    const wide_t ya = min_w(y1, y2) - (lo_cap == CapProjecting ? ext : 0);
53	    const wide_t yb = max_w(y1, y2) + (hi_cap == CapProjecting ? ext : 0);
54	    fill_box(c, x1 - before, ya, x1 - before + w - 1, yb, colour);
