58	/* Clips the segment to the canvas grown by margin, in double, because the
59	 * ends can be anywhere in the int range. Returns 0 when nothing is left. */
60	static int clip_to_canvas(const Canvas *c, wide_t margin, double *x1,
61	                          double *y1, double *x2, double *y2) {
62	  const double xmin = -(double)margin, xmax = (double)c->w + margin;
63	  const double ymin = -(double)margin, ymax = (double)c->h + margin;
64	  const double dx = *x2 - *x1, dy = *y2 - *y1;
65	  const double p[4] = {-dx, dx, -dy, dy};
66	  const double q[4] = {*x1 - xmin, xmax - *x1, *y1 - ymin, ymax - *y1};
67	  double t0 = 0, t1 = 1;
68	  for (int i = 0; i < 4; i++) {
69	    if (p[i] == 0) {
70	      if (q[i] < 0) return 0;
71	    } else {
72	      const double t = q[i] / p[i];
73	      if (p[i] < 0) {
74	        if (t > t1) return 0;
75	        if (t > t0) t0 = t;
76	      } else {
77	        if (t < t0) return 0;
78	        if (t < t1) t1 = t;
79	      }
80	    }
81	  }
82	  const double ax = *x1 + t0 * dx, ay = *y1 + t0 * dy;
83	  const double bx = *x1 + t1 * dx, by = *y1 + t1 * dy;
84	  *x1 = ax;
85	  *y1 = ay;
86	  *x2 = bx;
87	  *y2 = by;
88	  return 1;
89	}
90	
91	/* Fills a convex polygon whose vertices are in pixel coordinates, where the
92	 * pixel at x, y has its centre at x + 0.5, y + 0.5. A pixel is drawn when its
93	 * centre is inside, the left and top edges excluded and the right and bottom
94	 * edges included. The vertices stay floats: canvas_fill_polygon takes ints,
95	 * which would move the edges of a thin line by up to half a pixel. */
96	static void fill_convex(Canvas *c, const float pts[][2], int n,
97	                        uint16_t colour) {
98	  float ymin = pts[0][1], ymax = ymin;
99	  for (int i = 1; i < n; i++) {
100	    ymin = fminf(ymin, pts[i][1]);
101	    ymax = fmaxf(ymax, pts[i][1]);
102	  }
103	  const wide_t y0 = max_w(0, (wide_t)floorf(ymin));
104	  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(ymax));
105	  for (wide_t y = y0; y <= y1; y++) {
106	    const float sy = (float)y + 0.5f;
107	    float xl = INFINITY, xr = -INFINITY;
108	    for (int i = 0, j = n - 1; i < n; j = i++) {
109	      const float yi = pts[i][1], yj = pts[j][1];
110	      if ((yi < sy && yj >= sy) || (yj < sy && yi >= sy)) {
111	        const float x = pts[i][0] + (sy - yi) / (yj - yi) * (pts[j][0] - pts[i][0]);
112	        xl = fminf(xl, x);
113	        xr = fmaxf(xr, x);
114	      }
115	    }
116	    if (xl > xr) continue;
117	    fill_box(c, (wide_t)floorf(xl - 0.5f) + 1, y, (wide_t)floorf(xr - 0.5f), y,
118	             colour);
119	  }
120	}
121	
122	/* Where a vertex's line runs, in pixel coordinates (see stroke.h). */
123	static float centre_offset(int w) { return (w & 1) ? 0.5f : 0.0f; }
124	
125	static vec2 vertex(int x, int y, int w) {
126	  const float o = centre_offset(w);
127	  return (vec2){(float)x + o, (float)y + o};
128	}
129	
130	/* A segment between two vertices already in pixel coordinates, as a quad. An
131	 * end with a butt or round cap is lengthened enough to cover the pixel at the
132	 * vertex (half a pixel on an axis-aligned line; up to 0.71 on a diagonal when
133	 * the width is even and the vertex is a pixel corner). A projecting cap is
134	 * half the width past the vertex. An end that meets another segment
135	 * (STROKE_NO_CAP) is not lengthened at all. */
136	static void segment_quad(Canvas *c, vec2 a, vec2 b, int cap1, int cap2, int w,
137	                         uint16_t colour) {
138	  const float dx = b.x - a.x, dy = b.y - a.y;
139	  const float len = sqrtf(dx * dx + dy * dy);
140	  if (len < 0.001f) return;
141	  const float ux = dx / len, uy = dy / len;
142	  const float half = (float)w / 2.0f;
143	  const float pixel_along = (0.5f - centre_offset(w)) * (ux + uy);
144	  /* A butt cap must reach the vertex pixel (at least half a pixel). A
145	   * projecting cap reaches half the width past the vertex, which covers it,
146	   * plus the vertex pixel's offset when that is past the vertex. */
147	  const float e1 = cap1 == STROKE_NO_CAP     ? 0.0f
148	                   : cap1 == CapProjecting   ? half + fmaxf(0.0f, -pixel_along)
149	                                             : fmaxf(0.5f, -pixel_along);
150	  const float e2 = cap2 == STROKE_NO_CAP     ? 0.0f
151	                   : cap2 == CapProjecting   ? half + fmaxf(0.0f, pixel_along)
152	                                             : fmaxf(0.5f, pixel_along);
153	  const float nx = -uy * half, ny = ux * half;
154	  const vec2 p = {a.x - ux * e1, a.y - uy * e1};
155	  const vec2 q = {b.x + ux * e2, b.y + uy * e2};
156	  const float quad[4][2] = {
157	      {p.x + nx, p.y + ny}, {q.x + nx, q.y + ny}, {q.x - nx, q.y - ny},
158	      {p.x - nx, p.y - ny}};
159	  fill_convex(c, quad, 4, colour);
160	}
161	
162	/* One slanted segment whose ends can be anywhere in the int range. Ends cut by
163	 * the clip are off screen anyway. */
164	static void slanted(Canvas *c, wide_t ix1, wide_t iy1, wide_t ix2, wide_t iy2,
165	                    int cap1, int cap2, int w, uint16_t colour) {
166	  double x1 = (double)ix1, y1 = (double)iy1, x2 = (double)ix2, y2 = (double)iy2;
167	  /* The clip is in double, which the S3 does in software, and floats are exact
168	   * well past any canvas, so only ends far outside need it. */
169	  const wide_t near = (wide_t)1 << 20;
170	  const int small = ix1 > -near && ix1 < near && iy1 > -near && iy1 < near &&
171	                    ix2 > -near && ix2 < near && iy2 > -near && iy2 < near;
172	  if (!small && !clip_to_canvas(c, (wide_t)w + 2, &x1, &y1, &x2, &y2)) return;
173	  const float o = centre_offset(w);
174	  segment_quad(c, (vec2){(float)x1 + o, (float)y1 + o},
175	               (vec2){(float)x2 + o, (float)y2 + o}, cap1, cap2, w, colour);
176	}
177	
178	void stroke_segment_ends(Canvas *c, const struct XshimGC *gc, int x1, int y1,
179	                         int x2, int y2, int cap_start, int cap_end) {
180	  const int w = gc->line_width;
181	  const uint16_t colour = (uint16_t)gc->foreground;
182	
183	  if (cap_start == CapRound) disc(c, x1, y1, w, colour);
184	  if (cap_end == CapRound) disc(c, x2, y2, w, colour);
185	
186	  if (x1 == x2 && y1 == y2) {
187	    if (cap_start == CapProjecting || cap_end == CapProjecting)
188	      axis_aligned(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
189	    return;
190	  }
191	  if (x1 == x2 || y1 == y2)
192	    axis_aligned(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
193	  else
194	    slanted(c, x1, y1, x2, y2, cap_start, cap_end, w, colour);
195	}
196	
197	void stroke_segment(Canvas *c, const struct XshimGC *gc, int x1, int y1, int x2,
198	                    int y2) {
199	  stroke_segment_ends(c, gc, x1, y1, x2, y2, gc->cap_style, gc->cap_style);
200	}
201	
202	/* The corner between a segment arriving along d1 and one leaving along d2
203	 * (unit vectors), at vertex (ix, iy). */
204	static void join_at(Canvas *c, int ix, int iy, vec2 d1, vec2 d2, int w,
205	                    int style, uint16_t colour) {
206	  const float dot = d1.x * d2.x + d1.y * d2.y;
207	  const float cross = d1.x * d2.y - d1.y * d2.x;
208	  if (fabsf(cross) < 1e-4f && dot > 0) return;
209	  if (style == JoinRound) {
210	    disc(c, ix, iy, w, colour);
211	    return;
212	  }
213	  const vec2 v = vertex(ix, iy, w);
214	  const float half = (float)w / 2.0f;
215	  const float side = cross > 0 ? -1.0f : 1.0f;
216	  const vec2 n1 = {-d1.y * side, d1.x * side}, n2 = {-d2.y * side, d2.x * side};
217	  const vec2 p1 = {v.x + n1.x * half, v.y + n1.y * half};
218	  const vec2 p2 = {v.x + n2.x * half, v.y + n2.y * half};
219	  /* Xlib's miter limit of 10: the miter is longer than ten widths when the
220	   * segments meet at less than about 11.5 degrees, i.e. dot < -0.98. */
221	  if (style == JoinMiter && dot >= -0.98f) {
222	    const float k = half / (1.0f + dot);
223	    const float quad[4][2] = {{v.x, v.y},
224	                              {p1.x, p1.y},
225	                              {v.x + (n1.x + n2.x) * k, v.y + (n1.y + n2.y) * k},
226	                              {p2.x, p2.y}};
227	    fill_convex(c, quad, 4, colour);
228	    return;
229	  }
230	  const float tri[3][2] = {{v.x, v.y}, {p1.x, p1.y}, {p2.x, p2.y}};
231	  fill_convex(c, tri, 3, colour);
232	}
233	
234	static vec2 direction(const int *from, const int *to) {
235	  const float dx = (float)((wide_t)to[0] - from[0]);
236	  const float dy = (float)((wide_t)to[1] - from[1]);
237	  const float len = sqrtf(dx * dx + dy * dy);
238	  return (vec2){dx / len, dy / len};
239	}
240	
241	void stroke_polyline(Canvas *c, const struct XshimGC *gc, const int *xy, int n,
242	                     int closed) {
243	  if (n <= 0) return;
244	  const int w = gc->line_width;
245	  const uint16_t colour = (uint16_t)gc->foreground;
246	
247	  int stack_v[2 * 64];
248	  int *v = stack_v;
249	  if (n > 64) {
250	    v = (int *)malloc((size_t)n * 2 * sizeof(int));
251	    if (!v) return;
252	  }
253	  int m = 0;
254	  for (int i = 0; i < n; i++) {
255	    if (m > 0 && xy[2 * i] == v[2 * (m - 1)] && xy[2 * i + 1] == v[2 * (m - 1) + 1])
256	      continue;
257	    v[2 * m] = xy[2 * i];
258	    v[2 * m + 1] = xy[2 * i + 1];
259	    m++;
260	  }
261	  if (closed && m > 1 && v[2 * (m - 1)] == v[0] && v[2 * (m - 1) + 1] == v[1]) m--;
262	
263	  if (m == 1 || (m == 2 && !closed)) {
264	    stroke_segment(c, gc, v[0], v[1], v[2 * (m - 1)], v[2 * (m - 1) + 1]);
265	  } else {
266	    const int nseg = closed ? m : m - 1;
267	    for (int i = 0; i < nseg; i++) {
268	      const int *a = v + 2 * i, *b = v + 2 * ((i + 1) % m);
269	      const int cap1 = (!closed && i == 0) ? gc->cap_style : STROKE_NO_CAP;
270	      const int cap2 = (!closed && i == nseg - 1) ? gc->cap_style : STROKE_NO_CAP;
271	      if (cap1 == CapRound) disc(c, a[0], a[1], w, colour);
272	      if (cap2 == CapRound) disc(c, b[0], b[1], w, colour);
273	      segment_quad(c, vertex(a[0], a[1], w), vertex(b[0], b[1], w), cap1, cap2, w,
274	                   colour);
275	    }
276	    const int first = closed ? 0 : 1, last = closed ? m : m - 1;
277	    for (int j = first; j < last; j++) {
278	      const int *prev = v + 2 * ((j + m - 1) % m), *at = v + 2 * j;
279	      const int *next = v + 2 * ((j + 1) % m);
280	      join_at(c, at[0], at[1], direction(prev, at), direction(at, next), w,
281	              gc->join_style, colour);
282	    }
283	  }
284	  if (v != stack_v) free(v);
285	}
